<div class="portal-shell"><?php require __DIR__.'/../includes/sidebar.php';?><main class="portal-main"><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><header class="portal-page-header"><div><span class="eyebrow">ADMIN OVERVIEW</span><h1 class="mt-2 mb-1">Good day, <?=e(current_user()['first_name']??'Francis')?>.</h1><p class="text-muted mb-0">A focused view of sales, orders, customers, finance, and stock health.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-coffee" href="<?=url('admin/users.php')?>"><i class="bi bi-people me-2"></i>Users</a><a class="btn btn-coffee" href="<?=url('staff/pos.php')?>"><i class="bi bi-shop me-2"></i>Open POS</a></div></header><section class="admin-dashboard-metrics"><article><span>Paid sales today</span><strong><?=money($metrics['sales_today'])?></strong><small><?=money($metrics['sales_30'])?> in last 30 days</small></article><article><span>Orders today</span><strong><?=$metrics['orders_today']?></strong><small><?=$metrics['pending']?> currently pending</small></article><article><span>Customers</span><strong><?=$metrics['users']['customers']?></strong><small><?=$metrics['new_customers']?> joined in 30 days</small></article><article class="<?=$inventory['low']>0?'metric-attention':''?>"><span>Low stock</span><strong><?=$inventory['low']?></strong><small><?=money((float)$inventory['value'])?> approx. stock value</small></article></section><div class="admin-dashboard-grid mt-4"><section class="portal-card admin-sales-card"><div class="panel-heading"><div><span class="eyebrow">SALES OVERVIEW</span><h2>Last 7 days</h2></div><span class="text-muted small">Verified paid payments</span></div><div class="admin-sales-bars"><?php foreach($sales as $d):$h=$maxSale>0?max(4,round(($d['total']/$maxSale)*100)):4;?><div class="admin-sales-day"><div class="admin-sales-value"><?=money($d['total'])?></div><div class="admin-sales-track"><span style="height:<?=$h?>%"></span></div><small><?=e($d['label'])?></small></div><?php endforeach;?></div></section><section class="portal-card"><div class="panel-heading"><div><span class="eyebrow">TOP PRODUCTS</span><h2>Popular items</h2></div></div><?php if(!$top):?><div class="empty-state compact"><p>No product sales yet.</p></div><?php else:?><div class="admin-top-products"><?php foreach($top as $i=>$p):?><div><span class="admin-rank"><?=$i+1?></span><div><strong><?=e($p['product_name'])?></strong><small><?=number_format((int)$p['qty'])?> item<?=((int)$p['qty']===1?'':'s')?> · <?=money((float)$p['revenue'])?></small></div></div><?php endforeach;?></div><?php endif;?></section></div><section class="portal-card mt-4"><div class="panel-heading"><div><span class="eyebrow">RECENT ORDERS</span><h2>Latest activity</h2></div><a class="btn btn-sm btn-outline-coffee" href="<?=url('staff/orders.php')?>">View all orders</a></div><?php if(!$recent):?><div class="empty-state compact"><i class="bi bi-receipt"></i><h3>No orders yet</h3></div><?php else:?><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Order</th><th>Customer</th><th>Type</th><th>Total</th><th>Payment</th><th>Status</th><th>Time</th></tr></thead><tbody><?php foreach($recent as $o):?><tr><td><a class="fw-semibold text-decoration-none" href="<?=url('staff/order-details.php?order='.rawurlencode($o['order_number']))?>"><?=e($o['order_number'])?></a></td><td><?=e($o['contact_name']?:'Walk-in Customer')?></td><td><?=e($o['order_source'])?> · <?=e($o['fulfillment_type'])?></td><td><strong><?=money((float)$o['total_amount'])?></strong></td><td><?=e($o['payment_method']?:'—')?><?php if($o['payment_status']):?><small class="d-block text-muted"><?=e($o['payment_status'])?></small><?php endif;?></td><td><span class="badge <?=status_badge_class((string)$o['status'])?>"><?=e($o['status'])?></span></td><td><?=e(date('M j g:i A',strtotime($o['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><section class="admin-quick-grid mt-4"><a href="<?=url('admin/products.php')?>"><i class="bi bi-cup-hot"></i><span><strong>Products</strong><small>Menu, pricing, options</small></span></a><a href="<?=url('admin/inventory.php')?>"><i class="bi bi-box-seam"></i><span><strong>Inventory</strong><small><?=$inventory['low']?> low-stock item<?=((int)$inventory['low']===1?'':'s')?></small></span></a><a href="<?=url('admin/payments.php')?>"><i class="bi bi-credit-card"></i><span><strong>Payments</strong><small><?=$payments['pending']?> pending review</small></span></a><a href="<?=url('admin/expenses.php')?>"><i class="bi bi-wallet2"></i><span><strong>Expenses</strong><small><?=money($expenses['month_amount'])?> this month</small></span></a><a href="<?=url('admin/activity-logs.php')?>"><i class="bi bi-clock-history"></i><span><strong>Activity logs</strong><small>Review system actions</small></span></a><a href="<?=url('admin/settings.php')?>"><i class="bi bi-gear"></i><span><strong>Settings</strong><small>Store & payment setup</small></span></a></section><section class="portal-card mt-4 report-dashboard-callout"><div><span class="eyebrow">REPORTING</span><h2 class="mb-1">Business performance reports</h2><p class="text-muted mb-0">Review sales, orders, stock, payments, product performance, and expenses with printable date filters.</p></div><a class="btn btn-coffee" href="<?=url('admin/reports.php')?>"><i class="bi bi-bar-chart me-2"></i>Open reports</a></section></main></div><?php require __DIR__.'/../includes/footer.php';?>
